      "syntax": "ansible-playbook site.yml --check --diff --limit test\nansible-lint site.yml",
      "exampleCode": "$ ansible-playbook site.yml --check --diff\nPLAY RECAP ***\nlocalhost : ok=2 changed=1 unreachable=0 failed=0",
