       "buggyCode": "$ git clone --filter=blob:none https://example.com/monorepo.git\n$ git log -p   # downloads every blob",
       "fixedCode": "$ git clone --filter=blob:none https://example.com/monorepo.git\n$ git checkout apps/web   # downloads only what is needed",
